* BANK2 -- Account detail screen with scrollable transaction
* history. The top 7 rows show the account summary (number, name,
* address, contact, balance, status). Rows 9..21 are the scrollable
* history (newest first). PF7/PF8 page; PF4 jumps to address-change,
* PF5 to close-confirm, PF6 to open-new-account, PF3 back to search.
MAP BANK2 SIZE 24x80
  FIELD AT 0,24 LEN 32 PROT BRIGHT COLOR=WHITE     "BRICKS BANK NA - ACCOUNT DETAIL"

  FIELD AT 1,2  LEN 11 PROT COLOR=BLUE             "Account #:"
  FIELD ACCT    AT 1,14 LEN 23 PROT BRIGHT COLOR=YELLOW
  FIELD AT 1,39 LEN 7  PROT COLOR=BLUE             "Status:"
  FIELD STATUS  AT 1,48 LEN 10 PROT COLOR=TURQUOISE
  FIELD AT 1,55 LEN 7  PROT COLOR=BLUE             "Opened:"
  FIELD OPENED  AT 1,64 LEN 10 PROT COLOR=TURQUOISE

  FIELD AT 2,2  LEN 11 PROT COLOR=BLUE             "Name:"
  FIELD NAME    AT 2,14 LEN 66 PROT COLOR=TURQUOISE

  FIELD AT 3,2  LEN 11 PROT COLOR=BLUE             "Street:"
  FIELD STREET  AT 3,14 LEN 60 PROT COLOR=TURQUOISE

  FIELD AT 4,2  LEN 11 PROT COLOR=BLUE             "City/ST/ZIP:"
  FIELD CITYLN  AT 4,14 LEN 56 PROT COLOR=TURQUOISE

  FIELD AT 5,2  LEN 11 PROT COLOR=BLUE             "Phone:"
  FIELD PHONE   AT 5,14 LEN 15 PROT COLOR=TURQUOISE
  FIELD AT 5,32 LEN 7  PROT COLOR=BLUE             "Email:"
  FIELD EMAIL   AT 5,40 LEN 38 PROT COLOR=TURQUOISE

  FIELD AT 6,2  LEN 11 PROT COLOR=BLUE             "Balance:"
  FIELD BALANCE AT 6,14 LEN 18 PROT BRIGHT COLOR=YELLOW
  FIELD AT 6,40 LEN 40 PROT COLOR=BLUE             " "

  FIELD AT 7,0  LEN 80 PROT DIM COLOR=BLUE         "-------------------------------------------------------------------------------"

  FIELD AT 8,2  LEN 78 PROT DIM COLOR=TURQUOISE    "DATE/TIME         TYPE          AMOUNT    NEW BALANCE   DESCRIPTION"

  FIELD ROW1    AT 9,2  LEN 78 PROT COLOR=GREEN
  FIELD ROW2    AT 10,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW3    AT 11,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW4    AT 12,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW5    AT 13,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW6    AT 14,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW7    AT 15,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW8    AT 16,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW9    AT 17,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW10   AT 18,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW11   AT 19,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW12   AT 20,2 LEN 78 PROT COLOR=GREEN
  FIELD ROW13   AT 21,2 LEN 78 PROT COLOR=GREEN

  FIELD MSG     AT 22,2 LEN 76 PROT BRIGHT COLOR=RED
  FIELD AT 23,0 LEN 80 PROT DIM COLOR=BLUE         "PF3=Back PF7=PgUp PF8=PgDn PF4=Address PF5=Close Accnt PF6=Open NEW Accnt"
ENDMAP
